package propertyrental.platform.location.application.mapper;

import org.springframework.stereotype.Component;

import propertyrental.platform.location.api.dto.request.CreateProvinceRequest;
import propertyrental.platform.location.api.dto.request.UpdateProvinceRequest;
import propertyrental.platform.location.api.dto.response.ProvinceResponse;
import propertyrental.platform.location.infrastructure.persistence.entity.ProvinceEntity;

@Component
public class ProvinceMapper {

    // This builds a new entity from a create request (the id is generated by the database)
    public ProvinceEntity toEntity(CreateProvinceRequest request) {
        ProvinceEntity province = new ProvinceEntity();
        province.setCode(request.code());
        province.setName(request.name());

        return province;
    }

    // Apply an update request to an existing entity in place
    public void updateEntity(ProvinceEntity province, UpdateProvinceRequest request) {
        province.setCode(request.code());
        province.setName(request.name());
    }

    // This convert an entity to the response DTO, so the entity is never exposed
    public ProvinceResponse toResponse(ProvinceEntity province) {

        return new ProvinceResponse(
                province.getId(),
                province.getCode(),
                province.getName()
        );
    }
}